const fs = require('fs');
const path = require('path');

const DOSYA = path.join(__dirname, 'gorevler.json');

function yukle() {
  try {
    return JSON.parse(fs.readFileSync(DOSYA, 'utf8'));
  } catch {
    return [];
  }
}

function kaydet(gorevler) {
  fs.writeFileSync(DOSYA, JSON.stringify(gorevler, null, 2));
}

const [komut, ...args] = process.argv.slice(2);

if (!komut) {
  console.error('Kullanım: node gorev.js <ekle|liste|bitir> [argüman]');
  process.exit(1);
}

switch (komut) {
  case 'ekle': {
    const metin = args.join(' ').trim();
    if (!metin) {
      console.error('Hata: Görev metni boş olamaz.');
      process.exit(1);
    }
    const gorevler = yukle();
    gorevler.push({ metin, bitmis: false });
    kaydet(gorevler);
    console.log(`Eklendi: ${metin}`);
    break;
  }

  case 'liste': {
    const gorevler = yukle();
    if (gorevler.length === 0) {
      console.log('Görev yok.');
      break;
    }
    gorevler.forEach((g, i) => {
      const isaret = g.bitmis ? '[x]' : '[ ]';
      const metin = g.bitmis ? `${g.metin} (bitmiş)` : g.metin;
      console.log(`${i + 1}. ${isaret} ${metin}`);
    });
    break;
  }

  case 'bitir': {
    const no = parseInt(args[0], 10);
    const gorevler = yukle();
    if (isNaN(no) || no < 1 || no > gorevler.length) {
      console.error(`Hata: Geçersiz görev numarası: ${args[0]}`);
      process.exit(1);
    }
    gorevler[no - 1].bitmis = true;
    kaydet(gorevler);
    console.log(`Bitirildi: ${gorevler[no - 1].metin}`);
    break;
  }

  default:
    console.error(`Hata: Bilinmeyen komut "${komut}". Kullanılabilir komutlar: ekle, liste, bitir`);
    process.exit(1);
}

